questions.model:
@PostMapping("/users")
public ResponseEntity<UserResponse> create(@Valid @RequestBody CreateUserRequest req) {
  UserResponse out = service.create(req);
  return ResponseEntity.status(HttpStatus.CREATED).body(out);
}

@RestControllerAdvice
class ApiErrors {
  @ExceptionHandler(MethodArgumentNotValidException.class)
  ProblemDetail onInvalid(MethodArgumentNotValidException ex) {
    return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "Validation failed");
  }
}

public record CreateUserRequest(
    @NotBlank String name,
    @Email String email,
    @Min(18) int age) {}

@GetMapping("/users/{id}")
public UserResponse find(@PathVariable long id) {
  UserResponse u = service.find(id);
  if (u == null) throw new ResponseStatusException(HttpStatus.NOT_FOUND);
  return u;
}
